/**
 * Queueable job to re-rate Accounts based on their Annual Revenue.
 * Processes accounts in batches of 200 to respect governor limits and chains 
 * itself to process large volumes of records.
 */
public with sharing class AccountScoringJob implements Queueable {

    private List<Id> accountIds;

    /**
     * @param accountIds List of Account IDs to be processed in this batch and subsequent batches.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    /**
     * Entry point to start the scoring process.
     * 
     * @param accountIds List of Account IDs to process.
     * @return The ID of the first enqueued job, or null if the list is null or empty.
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    /**
     * Executes the scoring logic for a batch of up to 200 accounts.
     * 
     * @param context The queueable context.
     */
    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // 1. Determine the batch to process and the remaining IDs for chaining
        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        Integer totalCount = accountIds.size();
        Integer batchSize = Math.min(totalCount, 200);

        for (Integer i = 0; i < batchSize; i++) {
            batchIds.add(accountIds[i]);
        }

        for (Integer i = batchSize; i < totalCount; i++) {
            remainingIds.add(accountIds[i]);
        }

        try {
            // 2. Fetch accounts with User Mode enforcement
            List<Account> accountsToUpdate = [
                SELECT Id, AnnualRevenue 
                FROM Account 
                WHERE Id IN :batchIds 
                WITH USER_MODE
            ];

            // 3. Apply scoring logic
            for (Account acc : accountsToUpdate) {
                Decimal revenue = acc.AnnualRevenue;
                if (revenue != null && revenue >= 1000000) {
                    acc.Rating = 'Hot';
                } else if (revenue != null && revenue >= 100000) {
                    acc.Rating = 'Warm';
                } else {
                    acc.Rating = 'Cold';
                }
            }

            // 4. Perform DML with User Mode enforcement
            if (!accountsToUpdate.isEmpty()) {
                Database.update(accountsToUpdate, AccessLevel.USER_MODE);
            }

            // 5. Chain the next job if there are remaining IDs
            if (!remainingIds.isEmpty()) {
                System.enqueueJob(new AccountScoringJob(remainingIds));
            }

        } catch (Exception e) {
            // Rethrow to ensure the job is marked as failed in the UI.
            throw e;
        }
    }
}
