/**
 * Schedulable job to purge old integration logs.
 * Deletes non-ERROR logs older than 30 days and ERROR logs older than 180 days.
 */
public with sharing class LogPurgeJob implements Schedulable {

    /**
     * Default no-argument constructor.
     */
    public LogPurgeJob() {
    }

    /**
     * Executes the purge logic.
     * @param sc The schedulable context.
     */
    public void execute(SchedulableContext sc) {
        purgeLogs();
    }

    /**
     * Performs the deletion of old records.
     * To prevent hitting DML limits in a single transaction, this method 
     * limits the number of records processed per run.
     */
    private void purgeLogs() {
        Datetime thirtyDaysAgo = Datetime.now().addDays(-30);
        Datetime oneEightyDaysAgo = Datetime.now().addDays(-180);

        // Query for records to delete.
        // 1. ERROR logs created > 180 days ago.
        // 2. Non-ERROR logs (including null) created > 30 days ago.
        // Note: In SOQL, '!=' does not include NULL values, so we explicitly check for NULL.
        List<FB_Integration_Log__c> logsToPurge = [
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
               OR ((Level__c != 'ERROR' OR Level__c = NULL) AND CreatedDate < :thirtyDaysAgo)
            LIMIT 10000
        ];

        if (!logsToPurge.isEmpty()) {
            try {
                // Using Database.delete with allOrNone=false to allow partial success for bulk operations.
                Database.delete(logsToPurge, false);
            } catch (Exception e) {
                throw new LogPurgeException('An error occurred while purging integration logs.', e);
            }
        }
    }

    /**
     * Schedules the job to run every day at 02:00.
     * @return The Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        // Cron expression for 02:00 every day: 0 0 2 * * ?
        String cronExpression = '0 0 2 * * ?';
        LogPurgeJob job = new LogPurgeJob();
        return System.schedule('Log purge (nightly)', cronExpression, job);
    }

    /**
     * Custom exception for LogPurgeJob errors.
     */
    public class LogPurgeException extends Exception {}
}
