public class ContactPhoneCleanup {
    /**
     * Normalizes the Phone field of the provided Contact IDs.
     * Keeps only digits and the plus sign (+).
     * 
     * @param contactIds List of Contact IDs to process.
     * @return A map from the Id of each contact that could not be saved to its first error message.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorMap = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorMap;
        }

        // Query contacts provided in the list that actually have a phone number.
        // This fulfills the requirement that "contacts without a phone are left out".
        List<Contact> contactsToUpdate = [
            SELECT Id, Phone 
            FROM Contact 
            WHERE Id IN :contactIds 
            AND Phone != null
        ];

        if (contactsToUpdate.isEmpty()) {
            return errorMap;
        }

        for (Contact con : contactsToUpdate) {
            // Remove every character that is not a digit or a '+'
            // Inside a regex character class [], '+' is treated literally.
            con.Phone = con.Phone.replaceAll('[^0-9+]', '');
        }

        // Save all contacts with a single update call, allowing partial success.
        // This ensures a single record failing validation doesn't block the rest.
        Database.SaveResult[] results = Database.update(contactsToUpdate, false);

        // Iterate over the results to find any that failed to save.
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                // Capture the first error message from the failed record.
                String firstErrorMessage = results[i].getErrors()[0].getMessage();
                errorMap.put(contactsToUpdate[i].Id, firstErrorMessage);
            }
        }

        return errorMap;
    }
}
