/**
 * @description Handler class for Account triggers to synchronize BillingCountry to related Contact MailingCountry.
 * This class follows Salesforce best practices for bulkification, security, and resource management.
 */
public with sharing class AccountCountrySync {
    /**
     * @description Synchronizes the MailingCountry of related contacts when an Account's BillingCountry changes.
     * 
     * @param newAccs The list of accounts in the current trigger context (Trigger.new).
     * @param oldAccMap The map of accounts in the previous state (Trigger.oldMap).
     */
    public static void handleAfterUpdate(List<Account> newAccs, Map<Id, Account> oldAccMap) {
        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> accountOldCountryMap = new Map<Id, String>();
        Map<Id, String> accountNewCountryMap = new Map<Id, String>();

        // 1. Identify accounts where BillingCountry has changed and collect relevant data.
        for (Account acc : newAccs) {
            Account oldAcc = oldAccMap.get(acc.Id);
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccountIds.add(acc.Id);
                accountOldCountryMap.put(acc.Id, oldAcc.BillingCountry);
                accountNewCountryMap.put(acc.Id, acc.BillingCountry);
            }
        }

        // If no countries changed in this batch, exit early to save resources.
        if (changedAccountIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        /*
         * DEVIATION FROM PROPOSED APPROACH EXPLANATION:
         * 
         * The proposed approach suggested loading all contacts into a map using:
         * [SELECT Id, AccountId, MailingCountry FROM Contact]
         * 
         * I have changed this to:
         * [SELECT Id, AccountId, MailingCountry FROM Contact WHERE AccountId IN :changedAccountIds]
         * 
         * REASONS FOR CHANGE:
         * 1. SOQL Row Limits: The org contains ~2.3 million contacts. A query attempting to 
         *    retrieve all contacts will immediately fail because it exceeds the Salesforce 
         *    limit of 50,000 rows per transaction.
         * 2. Heap Size Limits: Loading 2.3 million records into an Apex Map would consume 
         *    massive amounts of memory, exceeding the Apex heap size limit and causing 
         *    the transaction to crash.
         * 3. Performance: Querying the entire Contact table is a "full table scan" which is 
         *    highly inefficient and will lead to query timeouts in a large-scale production environment.
         * 
         * PROD-READY APPROACH:
         * By filtering the query with `WHERE AccountId IN :changedAccountIds`, we only retrieve 
         * the contacts that are actually affected by the current transaction. This is 
         * bulk-safe, respects all platform limits, and ensures high performance.
         */
        for (Contact con : [SELECT Id, AccountId, MailingCountry FROM Contact WHERE AccountId IN :changedAccountIds]) {
            String oldCountry = accountOldCountryMap.get(con.AccountId);
            String newCountry = accountNewCountryMap.get(con.AccountId);

            // Logic: Update if MailingCountry is blank OR equal to the account's previous BillingCountry.
            if (String.isBlank(con.MailingCountry) || con.MailingCountry == oldCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        // 2. Perform a single bulk DML operation for the updated contacts.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
