import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    _options = [];
    _value;

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = value;
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(value) {
        this._value = value;
        this._syncActiveIndex();
    }

    activeIndex = 0;

    _syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this.activeIndex = 0;
            return;
        }
        const index = this._options.findIndex(opt => opt.value === this._value);
        this.activeIndex = index !== -1 ? index : 0;
    }

    get activeOptionId() {
        if (this._options && this._options.length > 0) {
            return `option-${this.activeIndex}`;
        }
        return '';
    }

    get displayedOptions() {
        if (!this._options) {
            return [];
        }
        return this._options.map((option, index) => ({
            ...option,
            id: `option-${index}`,
            isSelected: option.value === this._value
        }));
    }

    handleKeyDown(event) {
        if (!this._options || this._options.length === 0) {
            return;
        }

        const { key } = event;
        let handled = false;

        switch (key) {
            case 'ArrowDown':
                if (this.activeIndex < this._options.length - 1) {
                    this.activeIndex++;
                }
                handled = true;
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                }
                handled = true;
                break;
            case 'Home':
                this.activeIndex = 0;
                handled = true;
                break;
            case 'End':
                this.activeIndex = this._options.length - 1;
                handled = true;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this._options[this.activeIndex]?.value);
                handled = true;
                break;
            default:
                return;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const val = event.currentTarget.dataset.value;
        const index = this._options.findIndex(opt => opt.value === val);
        this.activeIndex = index !== -1 ? index : 0;
        this.selectOption(val);
    }

    selectOption(val) {
        if (val !== this._value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: val }
            }));
        }
    }
}
