public class FamilyService {
    /**
     * Links parents to children in NPSP.
     * 
     * @param parentIdByChildId A map where keys are Child Contact IDs and values are Parent Contact IDs.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Gather all Contact IDs involved to minimize SOQL scope and handle bulk limits.
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId != null) {
                contactIds.add(childId);
            }
        }
        for (Id parentId : parentIdByChildId.values()) {
            if (parentId != null) {
                contactIds.add(parentId);
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        // To avoid duplicates, check existing relationships in both directions.
        // Using a Set of concatenated IDs allows for O(1) lookup.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds OR npe4__RelatedContact__c IN :contactIds
        ]) {
            Id c1 = rel.npe4__Contact__c;
            Id c2 = rel.npe4__RelatedContact__c;
            if (c1 != null && c2 != null) {
                existingPairs.add(c1 + '-' + c2);
                existingPairs.add(c2 + '-' + c1);
            }
        }

        List<npe4__Relationship__c> newRelationships = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null) {
                continue;
            }

            // The requirement specifies skipping if any relationship already exists in either direction.
            String pairKey = childId + '-' + parentId;
            if (!existingPairs.contains(pairKey)) {
                newRelationships.add(new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
                ));

